                ...(lastMessageId && { before: lastMessageId }), // Adiciona o parâmetro "before" apenas se lastMessageId existir
            };

            const response = await axios.get(url, {
                headers: {
                    'Authorization': `<REDACTED>`,
                    'Content-Type': 'application/json',
                },
                params,
            });

            const data = response.data;
            if (data.length === 0) break; // Sai do loop se não houver mais mensagens

            for (const message of data) {
                const messageDate = new Date(message.timestamp);
                if (messageDate < TARGET_DATE) {
                    //console.log('Alcançou a data alvo.');
                    node.warn('Alcançou a data alvo');
                    return messages; // Retorna as mensagens coletadas
                }
                if (message.content != "") {
                    messages.push({
                        content: message.content,
                        timestamp: message.timestamp
                    });
                }
                lastMessageId = message.id;
            }
        }
    } catch (error) {
        node.warn('Erro ao buscar mensagens:');
        node.warn(error.response?.data || error.message);
    }

    return messages;
}

