let threadname = `${assunto} (${msg.infos.userId})`;
let threadmessage;

if (threadname.length > 99) {
    threadname = assunto;
    let arr = threadname.split('');
    do {
        arr.pop();
    } while (arr.length > 96);
    threadname = arr.join('');
    threadname = threadname + "...";

    threadmessage = `identificador:${msg.infos.userId}` + "\n" + msg.infos.ticketUrl + "\n" + msg.infos.anotacao;
}
else {
    threadmessage = msg.infos.ticketUrl + "\n" + msg.infos.anotacao;
}

axios.post(`https://discord.com/api/v10/channels/${channelId}/threads`, {
    name: `${threadname}`,
    auto_archive_duration: 60,  // Substitua pelo valor desejado em minutos
    type: 11,  // Indica uma thread de notícias, ajuste conforme necessário
},
{
    headers: {
        'Authorization': `<REDACTED>`,
    },
})
.then(threadResponse => {
    msg.step = "step-2";
    // Verifique a resposta da criação da thread

    // Enviar uma mensagem para a thread
    threadId = threadResponse.data.id;
    return axios.post(`https://discord.com/api/v10/channels/${threadId}/messages`, {
        content: threadmessage
    },
    {
        headers: {
            'Authorization': `<REDACTED>`,
        },
    });
})
.then(messageResponse => {
    // Verifique a resposta do envio da mensagem
    msg.step = "step-3";
    return axios.post(`https://discord.com/api/v10/channels/${threadId}/messages`, {
        //Quando é uma role, precisa ter o @&, usuários apenas o @
        content: `<@&889598102443528273> <@${csTeamDiscordIds[msg.infos.responsavel_cs] || 753226830584217610}>`,
        //content: `<@1050027476719517749>`,
    },
    {
        headers: {
            'Authorization': `<REDACTED>`,
        },
    });
})
.catch(error => {
    node.warn(error);
    msg.payload = error.message
    return node.send([msg, null]);
});

