function getYesterday() {
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(today.getDate() - 1);
    return yesterday.getTime();
}

function getDate7DaysAgo() {
    const today = new Date();
    const date7DaysAgo = new Date(today);
    date7DaysAgo.setDate(today.getDate() - 7);
    return date7DaysAgo.getTime();
}

function verifiesIfBetweenDates(date, upperDate, downDate) {
    const tmpDate = new Date(date).getTime();
    //const tmpUpperDate = new Date(upperDate).getTime();
    //const tmpDownDate = new Date(downDate).getTime();
    if (tmpDate >= downDate && tmpDate <= upperDate) {
        return true;
    }
    return false;
}

function getFormattedDate() {
    const today = new Date();

    const day = today.getDate().toString().padStart(2, '0');
    const month = (today.getMonth() + 1).toString().padStart(2, '0'); // Os meses são indexados a partir de zero, então adicionamos 1

    return `${day}/${month}`;
    //return formattedDate;
}

