(async () => {
    // ==========================================
    // 1. Configurações Iniciais
    // ==========================================
    // Cole aqui o seu token já em base64
    const meuTokenBase64 = '<REDACTED>'; 
    const baseUrl = 'https://ozmap.atlassian.net';
    const pastaInicialId = '1579974658';

    const headers = {
        'Accept': 'application/json',
        'Authorization': `<REDACTED>`
    };

    // Objeto final que será enviado no msg.payload
    const resultados = {};

    // ==========================================
    // 2. Função Auxiliar de Extração (Cheerio)
    // ==========================================
    function extrairCampo($, busca, isStatus = false) {
        const elementoTd = $(`th:contains("${busca}")`).first().next('td');

        if (elementoTd.length > 0) {
            let textoLimpo = elementoTd.text().replace(/\s+/g, ' ').trim();

            // Tratamento especial para o campo Status
            if (isStatus) {
                const textoMinusculo = textoLimpo.toLowerCase();

                if (textoMinusculo.includes('ativo')) return 'ativo';
                if (textoMinusculo.includes('beta')) return 'beta';
                if (textoMinusculo.includes('legado')) return 'legado';
                if (textoMinusculo.includes('desenvolvimento')) return 'em desenvolvimento';
            }

            return textoLimpo;
        }
        return null;
    }

    // ==========================================
    // 3. Função para ler a Página e Extrair Dados
    // ==========================================
    async function processarPagina(pageId) {
        const url = `${baseUrl}/wiki/api/v2/pages/${pageId}?body-format=storage`;

        try {
            const response = await axios.get(url, { headers });
            const data = response.data;

            if (data?.body?.storage?.value) {
                const html = data.body.storage.value;
                const $ = cheerio.load(html);

                const sku = extrairCampo($, '1.SKU');

                if (sku) {
                    // Monta o link da documentação
                    let linkDocumentacao = null;
                    if (data._links && data._links.webui && data._links.base) {
                        linkDocumentacao = data._links.base + data._links.webui;
                    }

                    resultados[sku] = {
                        "sku": sku,
                        "nome_comercial": extrairCampo($, '2.Nome Comercial'),
                        "tipo": extrairCampo($, '3.Tipo'),
                        "produto_vinculado": extrairCampo($, 'Produto Vinculado'),
                        "status": extrairCampo($, '4.Status', true), // Normalização de status ativada
                        //"status": extrairCampo($, '4.Status'),
                        "descricao": extrairCampo($, '5.Descrição Breve'),
                        "documentacao": linkDocumentacao // Link injetado aqui
                    };
                }
            }
        } catch (error) {
            node.warn(`Falha ao ler a página ${pageId}: ${error.message}`);
        }
    }

    // ==========================================
    // 4. Função Recursiva para Varrer a Pasta
    // ==========================================
    async function processarPasta(folderId) {
        let nextPath = `/wiki/api/v2/folders/${folderId}/direct-children?limit=50`;
        let hasNext = true;

        while (hasNext) {
            try {
                const url = `${baseUrl}${nextPath}`;
                const response = await axios.get(url, { headers });
                const data = response.data;

                if (data?.results?.length > 0) {
                    for (const filho of data.results) {
                        if (filho.type === 'page') {
                            await processarPagina(filho.id);
                        } else if (filho.type === 'folder') {
                            await processarPasta(filho.id);
                        }
                    }
                }

                // Lida com a paginação da API (limite de 50 resultados por requisição)
                if (data?._links?.next) {
                    nextPath = data._links.next;
                } else {
                    hasNext = false;
                }

            } catch (error) {
                node.warn(`Falha ao ler a pasta ${folderId}: ${error.message}`);
                hasNext = false;
            }
        }
    }

    // ==========================================
    // 5. Execução Principal do Nó
    // ==========================================
    try {
        // Atualiza a bolinha embaixo do nó para mostrar que está processando
        node.status({ fill: "blue", shape: "dot", text: "Lendo Confluence..." });

        await processarPasta(pastaInicialId);

        // Prepara o objeto final formatado
        msg.payload = resultados;

        // Sinaliza conclusão visualmente
        node.status({ fill: "green", shape: "dot", text: "Concluído" });

        // Dispara a mensagem para a próxima etapa do fluxo
        node.send(msg);

    } catch (erroGeral) {
        node.error("Erro geral no script: ", erroGeral);
        node.status({ fill: "red", shape: "ring", text: "Erro" });
    }
})();

